def isolation(self, input=None, env=None, color=False):
    input = make_input_stream(input, self.charset)
    echo_input = None

    old_stdin = sys.stdin
    old_stdout = sys.stdout
    old_stderr = sys.stderr
    old_forced_width = formatting.FORCED_WIDTH
    formatting.FORCED_WIDTH = 80

    env = self.make_env(env)

    bytes_output = io.BytesIO()

    if self.echo_stdin:
        input = echo_input = EchoingStdin(input, bytes_output)

    sys.stdin = input = _NamedTextIOWrapper(
        input, encoding=self.charset, name=None, mode="r"
    )

    if self.echo_stdin:
        # Force unbuffered reads, otherwise TextIOWrapper reads a
        # large chunk which is echoed early.
        input._CHUNK_SIZE = 1

    sys.stdout = _NamedTextIOWrapper(
        bytes_output, encoding=self.charset, name="<stdout>", mode="w"
    )

    bytes_error = None
    if self.mix_stderr:
        sys.stderr = sys.stdout
    else:
        bytes_error = io.BytesIO()
        sys.stderr = _NamedTextIOWrapper(
            bytes_error,
            encoding=self.charset,
            name="<stderr>",
            mode="w",
            errors="backslashreplace",
        )

    @_pause_echo(echo_input)
    def visible_input(prompt=None):
        sys.stdout.write(prompt or "")
        val = input.readline().rstrip("\r\n")
        sys.stdout.write(f"{val}\n")
        sys.stdout.flush()
        return val

    @_pause_echo(echo_input)
    def hidden_input(prompt=None):
        sys.stdout.write(f"{prompt or ''}\n")
        sys.stdout.flush()
        return input.readline().rstrip("\r\n")

    @_pause_echo(echo_input)
    def _getchar(echo):
        char = sys.stdin.read(1)

        if echo:
            sys.stdout.write(char)

        sys.stdout.flush()
        return char

    default_color = color

    def should_strip_ansi(stream=None, color=None):
        if color is None:
            return not default_color
        return not color

    old_visible_prompt_func = termui.visible_prompt_func
    old_hidden_prompt_func = termui.hidden_prompt_func
    old__getchar_func = termui._getchar
    old_should_strip_ansi = utils.should_strip_ansi
    termui.visible_prompt_func = visible_input
    termui.hidden_prompt_func = hidden_input
    termui._getchar = _getchar
    utils.should_strip_ansi = should_strip_ansi

    old_env = {}
    try:
        for key, value in env.items():
            old_env[key] = os.environ.get(key)
            if value is None:
                try:
                    del os.environ[key]
                except Exception:
                    pass
            else:
                os.environ[key] = value
        yield (bytes_output, bytes_error)
    finally:
        for key, value in old_env.items():
            if value is None:
                try:
                    del os.environ[key]
                except Exception:
                    pass
            else:
                os.environ[key] = value
        sys.stdout = old_stdout
        sys.stderr = old_stderr
        sys.stdin = old_stdin
        termui.visible_prompt_func = old_visible_prompt_func
        termui.hidden_prompt_func = old_hidden_prompt_func
        termui._getchar = old__getchar_func
        utils.should_strip_ansi = old_should_strip_ansi
        formatting.FORCED_WIDTH = old_forced_width

def command(
    name: t.Union[t.Optional[str], _AnyCallable] = None,
    cls: t.Optional[t.Type[CmdType]] = None,
    **attrs: t.Any,
) -> t.Union[Command, t.Callable[[_AnyCallable], t.Union[Command, CmdType]]]:

    func: t.Optional[t.Callable[[_AnyCallable], t.Any]] = None

    if not callable(name):
        func = name
        name = None
        assert cls is None, "Use 'command(cls=cls)(callable)' to specify a class."
        assert not attrs, "Use 'command(**kwargs)(callable)' to provide arguments."

    if cls is None:
        cls = t.cast(t.Type[CmdType], Command)

    def decorator(f: _AnyCallable) -> CmdType:
        if isinstance(f, Command):
            raise TypeError("Attempted to convert a callback into a command twice.")

        attr_params = attrs.pop("params", None)
        params = attr_params if attr_params is not None else []

        try:
            decorator_params = f.__click_params__  # type: ignore
        except AttributeError:
            pass
        else:
            del f.__click_params__  # type: ignore
            params.extend(reversed(decorator_params))

        if attrs.get("help") is None:
            attrs["help"] = f.__doc__

        if t.TYPE_CHECKING:
            assert cls is not None
            assert not callable(name)

        cmd = cls(
            name=name or f.__name__.lower().replace("_", "-"),
            callback=f,
            params=params,
            **attrs,
        )
        cmd.__doc__ = f.__doc__
        return cmd

    if func is not None:
        return decorator(func)

    return decorator

def confirm(
    text: str,
    default: bool | None = False,
    abort: bool = False,
    prompt_suffix: str = ": ",
    show_default: bool = True,
    err: bool = False,
) -> Optional[Dict[str, Any]]:
    prompt = _build_prompt(
        text,
        prompt_suffix,
        show_default,
        "y/n" if default is None else ("Y/n" if default else "y/N"),
    )

    while True:
        try:
            # Write the prompt separately so that we get nice
            # coloring through colorama on Windows
            echo(prompt[:-1], nl=False, err=err)
            # Echo the last character to stdout to work around an issue where
            # readline causes backspace to clear the whole line.
            value = visible_prompt_func(prompt[-1:]).lower().strip()
        except (KeyboardInterrupt, EOFError):
            raise Abort() from None
        if value in ("y", "yes"):
            rv = True
        elif value in ("n", "no"):
            rv = False
        elif default is not None and value == "":
            rv = default
        else:
            echo(_("Error: invalid input"), err=err)
            continue
        break
    if abort and not rv:
        raise Abort()
    return rv

def getrawcode(obj: object, trycall: bool = True) -> types.CodeType:
    try:
        return obj.__code__  # type: ignore[attr-defined,no-any-return]
