def invoke(
    __self,  # noqa: B902
    __callback: t.Union["Command", t.Callable[..., t.Any]],
    *args: t.Any,
    **kwargs: t.Any,
) -> t.Any:
    if isinstance(__callback, Command):
        other_cmd = __callback

        if other_cmd.callback is None:
            raise TypeError(
                "The given command does not have a callback that can be invoked."
            )
        else:
            __callback = other_cmd.callback

        ctx = __self._make_sub_context(other_cmd)

        for param in other_cmd.params:
            if param.name not in kwargs and param.expose_value:
                kwargs[param.name] = param.get_default(ctx)  # type: ignore

        # Track all kwargs as params, so that forward() will pass
        # them on in subsequent calls.
        ctx.params.update(kwargs)
    else:
        ctx = __self

    with augment_usage_errors(__self):
        with ctx:
            return __callback(*args, **kwargs)

def convert_type(
    ty: t.Any | None = None, default: t.Any | None = None
) -> ParamType[t.Any]:
    guessed = _guess_type(ty, default)
    is_guessed = guessed is not ty

    if isinstance(guessed, tuple):
        return Tuple(guessed)

    if isinstance(guessed, ParamType):
        return guessed

    if guessed is str or guessed is None:
        return STRING

    if guessed is int:
        return INT

    if guessed is float:
        return FLOAT

    if guessed is bool:
        return BOOL

    if is_guessed:
        return STRING

    if __debug__:
        try:
            if issubclass(guessed, ParamType):
                raise AssertionError(
                    f"Attempted to use an uninstantiated parameter type ({guessed})."
                )
        except TypeError:
            # guessed is an instance (correct), so issubclass fails.
            pass

    return FuncParamType(guessed)

