def build_lookup(self, lookups, lhs, rhs):
    # __exact is the default lookup if one isn't given.
    if len(lookups) == 0:
        lookups = ['exact']

    for name in lookups[:-1]:
        lhs = self.try_transform(lhs, name)
    # First try get_lookup() so that the lookup takes precedence if the lhs
    # supports both transform and lookup for the name.
    lookup_class = lhs.get_lookup(lookups[-1])
    if not lookup_class:
        if lhs.field.is_relation:
            raise FieldError('Related Field got invalid lookup: {}'.format(lookups[-1]))
        # A lookup wasn't found. Try to interpret the name as a transform
        # and do an Exact lookup against it.
        lhs = self.try_transform(lhs, lookups[-1])
        lookup_class = lhs.get_lookup('exact')

    if not lookup_class:
        return

    lookup = lookup_class(lhs, rhs)
    # Interpret '__exact=None' as the sql 'is NULL'; otherwise, reject all
    # uses of None as a query value.
    if lookup.rhs is None:
        if lookup.lookup_name not in ('exact', 'iexact'):
            raise ValueError("Cannot use None as a query value")
        return lhs.get_lookup('isnull')(lhs, True)

    # For Oracle '' is equivalent to null. The check must be done at this
    # stage because join promotion can't be done in the compiler. Using
    # DEFAULT_DB_ALIAS isn't nice but it's the best that can be done here.
    # A similar thing is done in is_nullable(), too.
    if (connections[DEFAULT_DB_ALIAS].features.interprets_empty_strings_as_nulls and
            lookup.lookup_name == 'exact' and lookup.rhs == ''):
        return lhs.get_lookup('isnull')(lhs, True)

    return lookup

def _alter_column_type_sql(
    self, model, old_field, new_field, new_type, old_collation, new_collation
):
    other_actions = []
    if collate_sql := self._collate_sql(
        new_collation, old_collation, model._meta.db_table
    ):
        collate_sql = f" {collate_sql}"
    else:
        collate_sql = ""
    # Comment change?
    comment_sql = ""
    if self.connection.features.supports_comments and not new_field.many_to_many:
        if old_field.db_comment != new_field.db_comment:
            # PostgreSQL and Oracle can't execute 'ALTER COLUMN ...' and
            # 'COMMENT ON ...' at the same time.
            sql, params = self._alter_column_comment_sql(
                model, new_field, new_type, new_field.db_comment
            )
            if sql:
                other_actions.append((sql, params))
        if new_field.db_comment:
            comment_sql = self._comment_sql(new_field.db_comment)
    return (
        (
            self.sql_alter_column_type
            % {
                "column": self.quote_name(new_field.column),
                "type": new_type,
                "collation": collate_sql,
                "comment": comment_sql,
            },
            [],
        ),
        other_actions,
    )

def model_to_dict(instance, fields=None, exclude=None):
    opts = instance._meta
    data = {}
    for f in chain(opts.concrete_fields, opts.private_fields, opts.many_to_many):
        if not getattr(f, 'editable', False):
            continue
        if fields and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        data[f.name] = f.value_from_object(instance)
    return data

