def __repr__(self) -> str:
    if _is_bool(self.expected) or not isinstance(self.expected, Complex | Decimal) or math.isinf(abs(self.expected)):
        return str(self.expected)
    try:
        if 0.001 <= self.tolerance < 1000.0:
            vetted_tolerance = f'{self.tolerance:n}'
        else:
            vetted_tolerance = f'{self.tolerance:.1e}'
        if isinstance(self.expected, Complex) and self.expected.imag and (not math.isinf(self.tolerance)):
            vetted_tolerance += ' ∠ ±180°'
    except ValueError:
        vetted_tolerance = '???'
    return f'{self.expected} ± {vetted_tolerance}'

def __eq__(self, actual) -> bool:
    asarray = _as_numpy_array(actual)
    if asarray is not None:
        return all((self.__eq__(a) for a in asarray.flat))
    if _is_bool(self.expected) and (not _is_bool(actual)):
        return False
    elif actual == self.expected:
        return True
    if _is_bool(self.expected) or not (isinstance(self.expected, Complex | Decimal) and isinstance(actual, Complex | Decimal)):
        return False
    if math.isnan(abs(self.expected)):
        return self.nan_ok and math.isnan(abs(actual))
    if math.isinf(abs(self.expected)):
        return False
    result: bool = abs(self.expected - actual) <= self.tolerance
    return result

@property
def tolerance(self):
    absolute_tolerance = self.abs if self.abs is not None else self.DEFAULT_ABSOLUTE_TOLERANCE
    if absolute_tolerance < 0:
        raise ValueError(f"absolute tolerance can't be negative: {absolute_tolerance}")
    if math.isnan(absolute_tolerance):
        raise ValueError("absolute tolerance can't be NaN.")
    if self.rel is None:
        if self.abs is not None:
            return absolute_tolerance
    rel = self.rel if self.rel is not None else self.DEFAULT_RELATIVE_TOLERANCE
    abs_expected: ExpectedT = abs(self.expected)
    relative_tolerance: float | Decimal = rel * abs_expected
    if relative_tolerance < 0:
        raise ValueError(f"relative tolerance can't be negative: {relative_tolerance}")
    if math.isnan(relative_tolerance):
        raise ValueError("relative tolerance can't be NaN.")
    return max(relative_tolerance, absolute_tolerance)

def approx(expected: T, rel: float | Decimal | timedelta | None=None, abs: float | Decimal | timedelta | None=None, nan_ok: bool=False) -> Approx[T]:
    __tracebackhide__ = True
    if isinstance(expected, Decimal):
        return ApproxDecimal(expected, rel=rel, abs=abs, nan_ok=nan_ok)
    elif isinstance(expected, Mapping):
        return ApproxMapping(expected, rel=rel, abs=abs, nan_ok=nan_ok)
    elif (np_array := _as_numpy_array(expected)) is not None:
        return ApproxNumpy(np_array, rel=rel, abs=abs, nan_ok=nan_ok)
    elif _is_sequence_like(expected):
        return ApproxSequenceLike(expected, rel=rel, abs=abs, nan_ok=nan_ok)
    elif isinstance(expected, Collection) and (not isinstance(expected, str | bytes)):
        msg = f'pytest.approx() only supports ordered sequences, but got: {expected!r}'
        raise TypeError(msg)
    elif isinstance(expected, (datetime, timedelta)):
        return ApproxTimedelta(expected, rel=rel, abs=abs, nan_ok=nan_ok)
    else:
        return ApproxScalar(expected, rel=rel, abs=abs, nan_ok=nan_ok)
